{
  "questoes": [
    {
      "enunciado": "Quais são as principais funções do tecido epitelial no corpo humano?",
      "resposta_esperada": "O tecido epitelial é responsável pelo revestimento do corpo e órgãos internos, além de atuar na absorção, secreção e proteção."
    },
    {
      "enunciado": "Como a falta de vascularização no tecido epitelial afeta sua função?",
